struct Vec3{float x,y,z;};struct Mat4{float m[16]{};};float dot(Vec3 a,Vec3 b)noexcept{return a.x*b.x+a.y*b.y+a.z*b.z;}Vec3 cross(Vec3 a,Vec3 b)noexcept{return{a.y*b.z-a.z*b.y,a.z*b.x-a.x*b.z,a.x*b.y-a.y*b.x};}Vec3 normalize(Vec3 v)noexcept{float l=std::sqrt(std::max(dot(v,v),1e-12f));return{v.x/l,v.y/l,v.z/l};}Mat4 identity()noexcept{Mat4 r{};r.m[0]=r.m[5]=r.m[10]=r.m[15]=1;return r;}Mat4 multiply(const Mat4&a,const Mat4&b)noexcept{Mat4 r{};for(int c=0;c<4;++c)for(int row=0;row<4;++row)for(int k=0;k<4;++k)r.m[c*4+row]+=a.m[k*4+row]*b.m[c*4+k];return r;}Mat4 translation(float x,float y,float z)noexcept{Mat4 r=identity();r.m[12]=x;r.m[13]=y;r.m[14]=z;return r;}Mat4 scale(float x,float y,float z)noexcept{Mat4 r{};r.m[0]=x;r.m[5]=y;r.m[10]=z;r.m[15]=1;return r;}Mat4 rotationX(float a)noexcept{Mat4 r=identity();float c=std::cos(a),s=std::sin(a);r.m[5]=c;r.m[9]=-s;r.m[6]=s;r.m[10]=c;return r;}Mat4 rotationY(float a)noexcept{Mat4 r=identity();float c=std::cos(a),s=std::sin(a);r.m[0]=c;r.m[8]=s;r.m[2]=-s;r.m[10]=c;return r;}Mat4 rotationZ(float a)noexcept{Mat4 r=identity();float c=std::cos(a),s=std::sin(a);r.m[0]=c;r.m[4]=-s;r.m[1]=s;r.m[5]=c;return r;}Mat4 lookAt(Vec3 eye,Vec3 center,Vec3 up)noexcept{Vec3 f=normalize({center.x-eye.x,center.y-eye.y,center.z-eye.z}),side=normalize(cross(f,up)),u=cross(side,f);Mat4 r=identity();r.m[0]=side.x;r.m[4]=side.y;r.m[8]=side.z;r.m[1]=u.x;r.m[5]=u.y;r.m[9]=u.z;r.m[2]=-f.x;r.m[6]=-f.y;r.m[10]=-f.z;r.m[12]=-dot(side,eye);r.m[13]=-dot(u,eye);r.m[14]=dot(f,eye);return r;}Mat4 perspective(float fov,float aspect,float n,float f)noexcept{Mat4 r{};float t=1/std::tan(fov*.5f);r.m[0]=t/aspect;r.m[5]=-t;r.m[10]=f/(n-f);r.m[11]=-1;r.m[14]=f*n/(n-f);return r;}
